// Cloud Functions v2 — Pontual Logística
// Endpoints SASCAR consumidos pelo frontend React via Firebase Auth ID token

import { onCall, HttpsError } from 'firebase-functions/v2/https';
import { defineSecret } from 'firebase-functions/params';
import { setGlobalOptions } from 'firebase-functions/v2';
import { initializeApp } from 'firebase-admin/app';

import {
  obterVeiculos,
  obterPacotePosicoes,
  ultimaPorVeiculo,
} from './src/sascar/soap.js';
import { cached } from './src/sascar/cache.js';

initializeApp();

setGlobalOptions({
  region: 'southamerica-east1',
  maxInstances: 5,
  memory: '256MiB',
  timeoutSeconds: 30,
});

const SASCAR_USUARIO = defineSecret('SASCAR_USUARIO');
const SASCAR_SENHA = defineSecret('SASCAR_SENHA');

function requireAuth(request) {
  if (!request.auth?.uid) {
    throw new HttpsError('unauthenticated', 'Login obrigatório');
  }
}

// --- sascarVeiculos: lista a frota (cache 1h) ---
export const sascarVeiculos = onCall(
  { secrets: [SASCAR_USUARIO, SASCAR_SENHA] },
  async (request) => {
    requireAuth(request);
    const { data, age, fresh } = await cached('veiculos', 3600_000, () =>
      obterVeiculos({
        usuario: SASCAR_USUARIO.value(),
        senha: SASCAR_SENHA.value(),
        quantidade: 1000,
        idVeiculo: 0,
      })
    );
    return { veiculos: data, total: data.length, cache: { age, fresh } };
  }
);

// --- sascarPosicoes: última posição por veículo (cache 30s) ---
export const sascarPosicoes = onCall(
  { secrets: [SASCAR_USUARIO, SASCAR_SENHA] },
  async (request) => {
    requireAuth(request);
    const { data, age, fresh } = await cached('posicoes', 30_000, async () => {
      const [pacotes, veiculos] = await Promise.all([
        obterPacotePosicoes({
          usuario: SASCAR_USUARIO.value(),
          senha: SASCAR_SENHA.value(),
          quantidade: 500,
        }),
        obterVeiculos({
          usuario: SASCAR_USUARIO.value(),
          senha: SASCAR_SENHA.value(),
          quantidade: 1000,
          idVeiculo: 0,
        }),
      ]);
      const placaPorId = new Map(veiculos.map(v => [v.idVeiculo, v.placa]));
      const ultimas = ultimaPorVeiculo(pacotes).map(p => ({
        ...p,
        placa: placaPorId.get(p.idVeiculo) ?? null,
        statusTexto: statusFromPacote(p),
      }));
      return ultimas;
    });
    return { posicoes: data, total: data.length, cache: { age, fresh } };
  }
);

function statusFromPacote(p) {
  if (p.bloqueio === 1) return 'BLOQUEADO';
  if (p.ignicao === 1 && (p.velocidade ?? 0) > 0) return 'EM_MOVIMENTO';
  if (p.ignicao === 1) return 'PARADO_LIGADO';
  return 'ESTACIONADO';
}

