let d=''; process.stdin.on('data',c=>d+=c).on('end',()=>{
  const r = JSON.parse(d).result;
  const now = Date.now();
  console.log('Total veículos retornados:', r.posicoes.length);
  const idades = r.posicoes.map(p => {
    const t = new Date(p.dataPosicao.replace('T',' ')).getTime();
    return { placa: p.placa, idadeMin: Math.round((now - t)/60000), gps: p.gps, vel: p.velocidade, ign: p.ignicao, status: p.statusTexto };
  }).sort((a,b) => a.idadeMin - b.idadeMin);
  console.log('Mais recente:', idades[0].placa, idades[0].idadeMin + ' min');
  console.log('Mais antigo: ', idades[idades.length-1].placa, idades[idades.length-1].idadeMin + ' min');
  console.log('---');
  console.log('Distribuição de idade:');
  const buckets = {'< 5 min':0, '5-15 min':0, '15-60 min':0, '1-6 h':0, '6-24 h':0, '> 24 h':0};
  idades.forEach(p => {
    if (p.idadeMin < 5) buckets['< 5 min']++;
    else if (p.idadeMin < 15) buckets['5-15 min']++;
    else if (p.idadeMin < 60) buckets['15-60 min']++;
    else if (p.idadeMin < 360) buckets['1-6 h']++;
    else if (p.idadeMin < 1440) buckets['6-24 h']++;
    else buckets['> 24 h']++;
  });
  for (const [k,v] of Object.entries(buckets)) console.log(' ', k.padEnd(12), '|', v);
  console.log('---');
  console.log('Sem sinal GPS (gps=0):', idades.filter(p => p.gps === 0).length);
  console.log('Mais velhos que 30 min:');
  idades.filter(p => p.idadeMin > 30).forEach(p => console.log(' ', p.placa.padEnd(11), p.idadeMin+'min', 'gps='+p.gps, p.status));
});
"

