  const novas = new Map();
  for (const p of ultimaPorVeiculo(pacotes)) novas.set(p.idVeiculo, p);

  // Mescla com últimas posições conhecidas guardadas em memória (sobrevive entre chamadas)
  for (const [id, prev] of ultimasConhecidas) {
    if (!novas.has(id)) novas.set(id, prev);
  }

  // Garante 1 registro por veículo cadastrado (mesmo sem nenhuma posição ainda)
  const resultado = [];
  for (const v of veiculos) {
    const p = novas.get(v.idVeiculo);
    if (p) {
      const enriched = {
        ...p,
        placa: v.placa,
        statusTexto: statusFromPacote(p),
        motoristaLogado: (p.idMotorista && p.idMotorista !== 0 && p.nomeMotorista) ? p.nomeMotorista.trim() : null,
