      ultimasConhecidas.set(v.idVeiculo, enriched);
      resultado.push(enriched);
    } else {
      resultado.push({
        idVeiculo: v.idVeiculo,
        placa: v.placa,
        statusTexto: "SEM_DADOS",
        motoristaLogado: null,
        latitude: null,
        longitude: null,
        dataPosicao: null,
      });
    }
  }
  return resultado;
});

