import { Polygon, Tooltip } from "react-leaflet";

// Áreas de interesse pra rastreamento — cada uma é um polígono lat/lon
// Refinar coordenadas via Google Maps quando tiver mais clientes
export const AREAS = [
  {
    nome: "Base PONTUAL",
    tipo: "base",
    cor: "#2563eb",
    pontos: [
      [-25.5490, -49.3700],
      [-25.5490, -49.3665],
      [-25.5520, -49.3665],
      [-25.5520, -49.3700],
    ],
  },
  {
    nome: "Replan / REPAR (Refinaria Petrobras)",
    tipo: "cliente",
    cor: "#16a34a",
    pontos: [
      [-25.5210, -49.4150],
      [-25.5210, -49.3940],
      [-25.5360, -49.3940],
      [-25.5360, -49.4150],
    ],
  },
];

// Algoritmo ray-casting — ponto está dentro do polígono?
export function pontoEmPoligono(lat, lon, pontos) {
  let dentro = false;
  for (let i = 0, j = pontos.length - 1; i < pontos.length; j = i++) {
    const xi = pontos[i][1], yi = pontos[i][0];
    const xj = pontos[j][1], yj = pontos[j][0];
    const intersect = ((yi > lat) !== (yj > lat)) &&
      (lon < (xj - xi) * (lat - yi) / (yj - yi) + xi);
    if (intersect) dentro = !dentro;
  }
  return dentro;
}

export function areaDoPonto(lat, lon) {
  if (!Number.isFinite(lat) || !Number.isFinite(lon)) return null;
  for (const a of AREAS) {
    if (pontoEmPoligono(lat, lon, a.pontos)) return a;
  }
  return null;
}

export default function CercaEletronica() {
  return (
    <>
      {AREAS.map(a => (
        <Polygon
          key={a.nome}
          positions={a.pontos}
          pathOptions={{
            color: a.cor,
            weight: 2,
            opacity: 0.9,
            fillColor: a.cor,
            fillOpacity: 0.15,
            dashArray: "6,4",
          }}
        >
          <Tooltip sticky direction="center" opacity={0.95}>
            <div style={{ fontWeight: 700, fontSize: ".82rem", color: a.cor }}>
              {a.nome}
            </div>
          </Tooltip>
        </Polygon>
      ))}
    </>
  );
}

