import { useEffect, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import { MapContainer, TileLayer, Polygon, Polyline, Marker, useMapEvents, Tooltip } from "react-leaflet";
import { divIcon } from "leaflet";
import { ArrowLeft, Plus, Trash2, X, Check } from "lucide-react";
import "leaflet/dist/leaflet.css";
import { collection, addDoc, deleteDoc, doc, serverTimestamp } from "firebase/firestore";
import { db } from "../firebase/config";
import { useCercas } from "../hooks/useCercas";
import { useAuth } from "../contexts/AuthContext";

const CORES = [
  { v: "#2563eb", n: "Azul" },
  { v: "#16a34a", n: "Verde" },
  { v: "#ea580c", n: "Laranja" },
  { v: "#dc2626", n: "Vermelho" },
  { v: "#7c3aed", n: "Roxo" },
];

const TIPOS = ["Base", "Cliente", "Restrita", "Outro"];

const CENTRO = [-25.5504, -49.3682]; // Araucária

function vertexIcon() {
  return divIcon({
    html: `<div style="width:10px;height:10px;background:#1a3a5c;border:2px solid #fff;border-radius:50%;box-shadow:0 1px 2px rgba(0,0,0,0.4)"></div>`,
    className: "vertex-icon",
    iconSize: [14, 14],
    iconAnchor: [7, 7],
  });
}

function MapClickHandler({ drawing, onClick }) {
  useMapEvents({
    click(e) {
      if (drawing) onClick([e.latlng.lat, e.latlng.lng]);
    },
  });
  return null;
}

export default function Cercas() {
  const navigate = useNavigate();
  const { cercas, loading } = useCercas();
  const { user } = useAuth();

  const [drawing, setDrawing] = useState(false);
  const [pontos, setPontos] = useState([]);
  const [modal, setModal] = useState(false);
  const [nome, setNome] = useState("");
  const [tipo, setTipo] = useState("Base");
  const [cor, setCor] = useState(CORES[0].v);
  const [salvando, setSalvando] = useState(false);

  function iniciarDesenho() {
    setDrawing(true);
    setPontos([]);
  }

  function cancelarDesenho() {
    setDrawing(false);
    setPontos([]);
    setModal(false);
    setNome("");
  }

  function concluirDesenho() {
    if (pontos.length < 3) return;
    setModal(true);
    setDrawing(false);
  }

  function adicionarPonto(latlng) {
    setPontos(prev => [...prev, latlng]);
  }

  async function salvar() {
    if (!nome.trim() || pontos.length < 3) return;
    setSalvando(true);
    try {
      await addDoc(collection(db, "cercas_eletronicas"), {
        nome: nome.trim(),
        tipo,
        cor,
        pontos,
        criadoEm: serverTimestamp(),
        criadoPor: user?.email || "—",
      });
      cancelarDesenho();
    } catch (e) {
      alert("Erro ao salvar cerca: " + e.message);
    } finally {
      setSalvando(false);
    }
  }

  async function excluir(c) {
    if (!confirm(`Excluir cerca "${c.nome}"?`)) return;
    try {
      await deleteDoc(doc(db, "cercas_eletronicas", c.id));
    } catch (e) {
      alert("Erro ao excluir: " + e.message);
    }
  }

  return (
    <div style={{ minHeight: "100vh", background: "#f0f4f8", fontFamily: "system-ui" }}>
      <div style={{ padding: "0.75rem 1rem", display: "flex", alignItems: "center", justifyContent: "space-between", background: "#fff", borderBottom: "1px solid #e2e8f0" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
          <button onClick={() => navigate("/dashboard")} style={btnGhost}>
            <ArrowLeft size={18} /> Dashboard
          </button>
          <h1 style={{ margin: 0, color: "#1a3a5c", fontSize: "1.2rem" }}>Cercas Eletrônicas</h1>
        </div>
        <div style={{ display: "flex", gap: 8 }}>
          {!drawing ? (
            <button onClick={iniciarDesenho} style={btnPrimary}>
              <Plus size={16} /> Nova cerca
            </button>
          ) : (
            <>
              <button onClick={concluirDesenho} disabled={pontos.length < 3} style={{ ...btnPrimary, background: pontos.length >= 3 ? "#16a34a" : "#94a3b8" }}>
                <Check size={16} /> Concluir ({pontos.length} pontos)
              </button>
              <button onClick={cancelarDesenho} style={btnGhost}>
                <X size={16} /> Cancelar
              </button>
            </>
          )}
        </div>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "280px 1fr", height: "calc(100vh - 56px)" }}>
        {/* Sidebar */}
        <div style={{ background: "#fff", borderRight: "1px solid #e2e8f0", overflowY: "auto", padding: "0.75rem" }}>
          <div style={{ fontSize: ".75rem", fontWeight: 700, color: "#64748b", textTransform: "uppercase", marginBottom: 8 }}>
            Cercas salvas ({cercas.length})
          </div>
          {loading && <div style={{ color: "#94a3b8" }}>Carregando...</div>}
          {!loading && cercas.length === 0 && (
            <div style={{ color: "#94a3b8", fontSize: ".88rem", padding: "1rem", background: "#f8fafc", borderRadius: 8 }}>
              Nenhuma cerca ainda.<br/>Clique "+ Nova cerca" e clique no mapa pra desenhar.
            </div>
          )}
          {cercas.map(c => (
            <div key={c.id} style={{ padding: "0.6rem 0.75rem", background: "#f8fafc", borderRadius: 8, marginBottom: 6, borderLeft: `3px solid ${c.cor}` }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "start", gap: 6 }}>
                <div>
                  <div style={{ fontWeight: 700, color: "#1a3a5c", fontSize: ".88rem" }}>{c.nome}</div>
                  <div style={{ fontSize: ".72rem", color: "#64748b" }}>{c.tipo} · {c.pontos?.length || 0} pontos</div>
                </div>
                <button onClick={() => excluir(c)} title="Excluir" style={{ background: "transparent", border: "none", color: "#dc2626", cursor: "pointer", padding: 2 }}>
                  <Trash2 size={14} />
                </button>
              </div>
            </div>
          ))}

          {drawing && (
            <div style={{ marginTop: 16, padding: "0.75rem", background: "#fef9c3", borderRadius: 8, fontSize: ".82rem", color: "#854d0e" }}>
              <strong>Modo desenho:</strong><br/>
              Clique no mapa para adicionar pontos.<br/>
              Mínimo 3, clique "Concluir" quando terminar.
            </div>
          )}
        </div>

        {/* Mapa */}
        <div style={{ position: "relative" }}>
          <MapContainer center={CENTRO} zoom={13} style={{ height: "100%", width: "100%", cursor: drawing ? "crosshair" : "" }}>
            <TileLayer attribution='&copy; OpenStreetMap' url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />
            <MapClickHandler drawing={drawing} onClick={adicionarPonto} />

            {/* Cercas existentes */}
            {cercas.map(c => (
              <Polygon key={c.id} positions={c.pontos} pathOptions={{ color: c.cor, weight: 2, fillColor: c.cor, fillOpacity: 0.18, dashArray: "6,4" }}>
                <Tooltip sticky direction="center"><strong>{c.nome}</strong></Tooltip>
              </Polygon>
            ))}

            {/* Desenho em andamento */}
            {drawing && pontos.length >= 2 && (
              <Polyline positions={pontos} pathOptions={{ color: cor, weight: 3, dashArray: "4,4" }} />
            )}
            {drawing && pontos.length >= 3 && (
              <Polygon positions={pontos} pathOptions={{ color: cor, weight: 2, fillColor: cor, fillOpacity: 0.12 }} />
            )}
            {drawing && pontos.map((pt, i) => (
              <Marker key={i} position={pt} icon={vertexIcon()} />
            ))}
          </MapContainer>
        </div>
      </div>

      {/* Modal salvar */}
      {modal && (
        <div style={overlay}>
          <div style={card}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 12 }}>
              <h2 style={{ margin: 0, color: "#1a3a5c", fontSize: "1.05rem" }}>Salvar cerca</h2>
              <button onClick={cancelarDesenho} style={{ background: "none", border: "none", cursor: "pointer", color: "#64748b" }}>
                <X size={18} />
              </button>
            </div>

            <label style={lbl}>Nome</label>
            <input value={nome} onChange={e => setNome(e.target.value)} placeholder="Ex: Replan, Base PONTUAL, Cliente X..." style={inp} autoFocus />

            <label style={lbl}>Tipo</label>
            <select value={tipo} onChange={e => setTipo(e.target.value)} style={inp}>
              {TIPOS.map(t => <option key={t}>{t}</option>)}
            </select>

            <label style={lbl}>Cor</label>
            <div style={{ display: "flex", gap: 8, marginBottom: 16 }}>
              {CORES.map(c => (
                <button key={c.v} onClick={() => setCor(c.v)} style={{
                  width: 32, height: 32, borderRadius: 6,
                  background: c.v,
                  border: cor === c.v ? "3px solid #1a3a5c" : "2px solid #e2e8f0",
                  cursor: "pointer",
                }} title={c.n} />
              ))}
            </div>

            <div style={{ display: "flex", gap: 8, justifyContent: "flex-end" }}>
              <button onClick={cancelarDesenho} style={btnGhost}>Cancelar</button>
              <button onClick={salvar} disabled={!nome.trim() || salvando} style={{ ...btnPrimary, opacity: !nome.trim() || salvando ? 0.5 : 1 }}>
                {salvando ? "Salvando..." : "Salvar cerca"}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

const btnPrimary = { display: "inline-flex", alignItems: "center", gap: 6, padding: "0.5rem 0.9rem", background: "#1a3a5c", color: "#fff", border: "none", borderRadius: 8, fontWeight: 600, cursor: "pointer", fontSize: ".86rem" };
const btnGhost = { display: "inline-flex", alignItems: "center", gap: 6, padding: "0.45rem 0.8rem", background: "#fff", color: "#475569", border: "1px solid #cbd5e1", borderRadius: 8, fontWeight: 600, cursor: "pointer", fontSize: ".84rem" };
const overlay = { position: "fixed", inset: 0, background: "rgba(0,0,0,0.45)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 9999 };
const card = { background: "#fff", borderRadius: 12, padding: "1.25rem", width: 380, maxWidth: "90vw", boxShadow: "0 8px 24px rgba(0,0,0,0.2)" };
const lbl = { display: "block", fontSize: ".74rem", color: "#64748b", fontWeight: 700, textTransform: "uppercase", marginBottom: 4 };
const inp = { width: "100%", padding: "0.55rem 0.7rem", border: "1px solid #cbd5e1", borderRadius: 8, fontSize: ".92rem", marginBottom: 12, fontFamily: "system-ui", boxSizing: "border-box" };

