// Status do MOTOR (realidade física). Bloqueio armado é informação separada (bloqueioArmado).
function statusFromPacote(p) {
  const vel = p.velocidade ?? 0;
  const ign = p.ignicao === 1;
  if (ign && vel > 0) return 'EM_MOVIMENTO';
  if (ign) return 'PARADO_LIGADO';
  // Bloqueio efetivado: motor desligado + atuador armado
  if (p.bloqueio === 1) return 'BLOQUEADO';
  return 'ESTACIONADO';
}

