echo "=== Emulator ==="; netstat -ano | findstr ":5001 .*LISTENING" | head -1
echo "=== Vite ==="; netstat -ano | findstr ":5173 .*LISTENING" | head -1
echo "=== Backend response ==="
curl -sS -X POST "http://127.0.0.1:5001/pontual-logistica/southamerica-east1/sascarPosicoes" -H "Content-Type: application/json" -H "x-dev-bypass: true" -d "{\"data\":{}}" --max-time 10 | node -e "
let d='';process.stdin.on('data',c=>d+=c).on('end',()=>{
  try {
    const r = JSON.parse(d);
    if (r.error) { console.log('ERRO:', r.error.message); return; }
    const p = r.result.posicoes;
    const counts = {};
    p.forEach(x => counts[x.statusTexto] = (counts[x.statusTexto]||0) + 1);
    console.log('Cache:', JSON.stringify(r.result.cache));
    console.log('Total:', r.result.total);
    console.log('Status:', counts);
    const semBLOQ = !p.some(x => x.statusTexto === 'BLOQUEADO');
    console.log('Status BLOQUEADO removido:', semBLOQ ? '✓' : '✗ AINDA APARECE');
    const comMot = p.filter(x => x.motoristaLogado).length;
    console.log('Com motorista logado:', comMot);
  } catch(e) { console.log('Erro parse:', d.slice(0,200)) }
});"

