// ── Componente ─────────────────────────────────────────────────────────────
export default function Manutencao() {
  const { profile } = useAuth();
  const navigate    = useNavigate();
  const canDelete   = ["master","admin"].includes(profile?.role);

  const [registros,      setRegistros]      = useState({});
